class Node:
    """Node class to store key-value pair and reference to parent and child for tree structure."""
    def __init__(self, key: int, value: int):
        self.key = key
        self.value = value
        self.parent = None
        self.children = []

class LRUCache:
    """
    A Least Recently Used (LRU) Cache implementation using a hash map for O(1) access
    and a tree structure to maintain the order of usage, allowing fast updates and removals.
    """
    def __init__(self, capacity: int):
        self.capacity = capacity
        self.cache = {}
        self.root = Node(0, 0)  # dummy root
        self.size = 0

    def _move_to_root(self, node: Node) -> None:
        if node.parent:
            node.parent.children.remove(node)
            node.parent = self.root
            self.root.children.append(node)

    def get(self, key: int) -> int:
        if key in self.cache:
            node = self.cache[key]
            self._move_to_root(node)
            return node.value
        return -1

    def put(self, key: int, value: int) -> None:
        if key in self.cache:
            node = self.cache[key]
            node.value = value
            self._move_to_root(node)
        else:
            if self.size == self.capacity:
                lru_node = self.root.children.pop(0)  # remove LRU from children
                del self.cache[lru_node.key]
            new_node = Node(key, value)
            new_node.parent = self.root
            self.root.children.append(new_node)
            self.cache[key] = new_node
            self.size += 1
